use crate::aap::caps::{http_client, notifier};
use crate::wasi::clocks::wall_clock;

struct Node;

/// How many times to offer the notification before giving up. The contract
/// requires `notified == true` on every output, so a report claiming
/// otherwise must never be produced; a persistently refused notification
/// traps instead of fabricating acceptance.
const NOTIFY_ATTEMPTS: u32 = 3;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // 1. Read the clock.
        let now = wall_clock::now();
        let seconds = now.seconds;

        // 2. One permitted fetch. A transport failure is a value; a host outside
        //    the allowlist traps at the boundary, which we do not try to avoid.
        let (fetched, fetch_note) = match http_client::fetch(&feed_url) {
            Ok(body) => {
                let n = body.chars().count();
                let n = u32::try_from(n).unwrap_or(u32::MAX);
                (n, format!("fetched {} chars", n))
            }
            Err(err) => (0u32, format!("fetch failed: {}", truncate(&err, 200))),
        };

        // 3. Notify the digest channel.
        let message = format!(
            "heartbeat at {}s: {} from {}",
            seconds,
            fetch_note,
            truncate(&feed_url, 200)
        );

        let mut notified = false;
        for _ in 0..NOTIFY_ATTEMPTS {
            if notifier::notify(&message) {
                notified = true;
                break;
            }
        }

        if !notified {
            // Producing `notified: false` would violate `ensures notified == true`;
            // reporting `true` would be a lie. Trap instead.
            panic!("notification was not accepted by the digest channel");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

/// Bound a string to at most `max` characters, on a char boundary.
fn truncate(s: &str, max: usize) -> &str {
    match s.char_indices().nth(max) {
        Some((idx, _)) => &s[..idx],
        None => s,
    }
}

export!(Node);
